 import { execSync } from 'child_process';
 import path from 'path';

 const UPLOAD_DIR = process.env.UPLOAD_DIR ?? '/var/uploads';
+
+/** Renders the first page of an uploaded PDF as a PNG preview next to it, and returns the preview's path. */
+export function renderPreview(uploadName: string): string {
+  const source = path.join(UPLOAD_DIR, uploadName);
+  execSync(`pdftoppm -png -singlefile ${source} ${source}`);
+  return `${source}.png`;
+}
